def solution():
    import math
    # weights
    w = {'X': 0.5, 'Y': 0.3, 'Z': 0.2}
    # standard deviations
    sigma = {'X': 0.10, 'Y': 0.12, 'Z': 0.08}
    # correlations
    rho = {'XY': 0.40, 'XZ': 0.20, 'YZ': 0.50}
    # covariances
    cov = {
        'XY': rho['XY'] * sigma['X'] * sigma['Y'],
        'XZ': rho['XZ'] * sigma['X'] * sigma['Z'],
        'YZ': rho['YZ'] * sigma['Y'] * sigma['Z']
    }
    # variance components
    var = (w['X'] ** 2) * (sigma['X'] ** 2) + (w['Y'] ** 2) * (sigma['Y'] ** 2) + (w['Z'] ** 2) * (sigma['Z'] ** 2)
    var += 2 * w['X'] * w['Y'] * cov['XY']
    var += 2 * w['X'] * w['Z'] * cov['XZ']
    var += 2 * w['Y'] * w['Z'] * cov['YZ']
    return math.sqrt(var)

