def solution():
    import math
    face = 1000.0
    coupon_annual = 0.05 * face
    # Semi‑annual coupon amount
    coupon = coupon_annual / 2
    # Cash‑flow schedule (six payments, last includes principal)
    cashflows = [coupon] * 5 + [coupon + face]
    times = [0.5, 1, 1.5, 2, 2.5, 3]
    # Zero rates (continuously compounded) at whole years
    zero = {1: 0.035, 2: 0.04, 3: 0.045}
    def get_rate(t):
        if t <= 1:
            return zero[1]
        elif t <= 2:
            # Linear interpolation between year 1 and 2
            return zero[1] + (zero[2] - zero[1]) * (t - 1) / (2 - 1)
        else:
            # Linear interpolation between year 2 and 3
            return zero[2] + (zero[3] - zero[2]) * (t - 2) / (3 - 2)
    price = 0.0
    for cf, t in zip(cashflows, times):
        r = get_rate(t)
        price += cf * math.exp(-r * t)
    return price

