def solution():
    import math
    # Weights
    w = [0.30, 0.50, 0.20]
    # Standard deviations
    sigma = [0.15, 0.25, 0.10]
    # Correlation dictionary (i<j)
    rho = {
        (0, 1): 0.20,
        (0, 2): 0.10,
        (1, 2): 0.40
    }
    # Build covariance matrix
    cov = [[0.0 for _ in range(3)] for _ in range(3)]
    for i in range(3):
        for j in range(3):
            if i == j:
                cov[i][j] = sigma[i] ** 2
            else:
                key = (i, j) if (i, j) in rho else (j, i)
                cov[i][j] = rho[key] * sigma[i] * sigma[j]
    # Portfolio variance = w' * Cov * w
    var = 0.0
    for i in range(3):
        for j in range(3):
            var += w[i] * w[j] * cov[i][j]
    std_dev = math.sqrt(var)
    return std_dev

def solution():
    cf0 = -500000
    cfs = [120000, 150000, 180000, 210000, 250000]
    def npv(r):
        total = cf0
        for t, cf in enumerate(cfs, start=1):
            total += cf / (1 + r) ** t
        return total
    low, high = 0.0, 1.0
    for _ in range(100):
        mid = (low + high) / 2
        if npv(mid) > 0:
            low = mid
        else:
            high = mid
        if high - low < 1e-7:
            break
    return (low + high) / 2

def solution():
    import math
    cf0 = -200
    inflows = [80, 90, 100]
    def npv(r):
        return cf0 + sum(cf / (1 + r) ** (i + 1) for i, cf in enumerate(inflows))
    low, high = 0.0, 1.0
    for _ in range(100):
        mid = (low + high) / 2
        if npv(mid) > 0:
            low = mid
        else:
            high = mid
    return (low + high) / 2

