    # Correlations matrix (symmetric)
    rho = {
        (0, 1): 0.20,
        (0, 2): 0.40,
        (1, 2): 0.30,
    }
    # Build covariance matrix
    cov = [[0.0 for _ in range(3)] for _ in range(3)]
    for i in range(3):
        for j in range(3):
            if i == j:
                cov[i][j] = sigma[i] ** 2
            else:
                # ensure ordering for rho lookup
                key = (i, j) if (i, j) in rho else (j, i)
                cov[i][j] = rho[key] * sigma[i] * sigma[j]
    # Portfolio variance = w' * cov * w
    var = 0.0
    for i in range(3):
        for j in range(3):
            var += w[i] * cov[i][j] * w[j]
    std_dev = math.sqrt(var)
    return std_dev

