def solution():
    import math
    w = [0.25, 0.35, 0.40]
    sigma = [0.12, 0.18, 0.22]
    rho = {(0, 1): 0.25, (0, 2): 0.10, (1, 2): 0.35}
    var = 0.0
    for i in range(3):
        var += w[i] ** 2 * sigma[i] ** 2
    for (i, j), r in rho.items():
        cov = r * sigma[i] * sigma[j]
        var += 2 * w[i] * w[j] * cov
    return var

