def solution():
    import math
    cash_flows = {
        0: -200000,
        1: 50000,
        2: 60000,
        3: 70000,
        4: 80000,
        5: 90000
    }
    def npv(rate):
        return sum(cf / (1 + rate) ** t for t, cf in cash_flows.items())
    # Bisection method between 0% and 30%
    low, high = 0.0, 0.30
    for _ in range(100):
        mid = (low + high) / 2
        val = npv(mid)
        if abs(val) < 1e-8:
            break
        if val > 0:
            low = mid
        else:
            high = mid
    return (low + high) / 2

