def solution():
    import math
    initial = -85000.0
    cf = 25000.0
    years = 5
    # NPV function for a given rate r
    def npv(r):
        return initial + sum(cf / ((1 + r) ** t) for t in range(1, years + 1))
    # Bisection method between 0% and 100%
    low, high = 0.0, 1.0
    for _ in range(100):
        mid = (low + high) / 2
        if npv(mid) > 0:
            low = mid
        else:
            high = mid
        if high - low < 1e-8:
            break
    return (low + high) / 2

