def solution():
    cash = [-100000, 30000, 40000, 50000]
    def npv(r):
        return sum(cf / ((1 + r) ** t) for t, cf in enumerate(cash))
    lo, hi = 0.0, 1.0
    # Ensure the root is bracketed
    while npv(lo) < 0:
        lo += 0.1
    while npv(hi) > 0:
        hi -= 0.1
    for _ in range(100):
        mid = (lo + hi) / 2
        if npv(mid) > 0:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2

def solution():
    cash = [-120000, 30000, 45000, 55000, 65000]
    target = 5000.0
    def npv(r):
        return sum(cf / ((1 + r) ** t) for t, cf in enumerate(cash))
    lo, hi = 0.0, 1.0
    # NPV at lo > target, at hi < target (guaranteed by the range)
    for _ in range(100):
        mid = (lo + hi) / 2
        if npv(mid) > target:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2

def solution():
    r = 0.10
    projectA = [-80000, 30000, 35000, 40000]
    projectB = [-70000, 20000, 25000, 60000]
    def npv(cf):
        return sum(cf[t] / ((1 + r) ** t) for t in range(len(cf)))
    npvA = npv(projectA)
    npvB = npv(projectB)
    return max(npvA, npvB)

