def solution():
    import math
    spot = [0.03, 0.032, 0.035, 0.038, 0.04]
    coupon = 4.0
    price = 0.0
    for i, r in enumerate(spot, start=1):
        df = 1 / (1 + r) ** i
        if i < 5:
            price += coupon * df
        else:
            price += (coupon + 100) * df
    return price

